package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

func main() {
	var count atomic.Int64
	var wg sync.WaitGroup

	for range 1_000 {
		wg.Go(func() {
			count.Add(1)
		})
	}
	wg.Wait()

	got := count.Load()
	if got != 1_000 {
		panic(fmt.Sprintf("got %d", got))
	}
	fmt.Println(got)
}
```
The count is an independent value, and every concurrent access uses its atomic methods.

```go
package main

import (
	"fmt"
	"sync"
)

type Inventory struct {
	mu    sync.Mutex
	stock int
}

func (i *Inventory) Reserve() bool {
	i.mu.Lock()
	defer i.mu.Unlock()
	if i.stock == 0 {
		return false
	}
	i.stock--
	return true
}

func main() {
	items := &Inventory{stock: 1}
	var wg sync.WaitGroup
	accepted := make(chan bool, 2)
	for range 2 {
		wg.Go(func() { accepted <- items.Reserve() })
	}
	wg.Wait()
	close(accepted)

	winners := 0
	for ok := range accepted {
		if ok {
			winners++
		}
	}
	fmt.Println(winners)
}
```
Exactly one caller can check and consume the single item. The testable result is one accepted reservation.
